import { Types } from "./types";

const initialState = {
    count: 0,
};

export const counterReducer = (state = initialState, action) => {
    switch (action.type) {
        case Types.increaseCount:
            console.log('increase', state)

            return {
                count: state.count +=1,
            };
        case Types.decreaseCount:
            console.log('decrease', state)
            return {
                count: state.count -=1,
            }
        default:
            return state;
    }
}
